function getChartLabels(resource, data) {
    switch (resource) {
        case 'bandwidth':
            let bandwidthData = data;
            let bandwidthDatasets = [];
            for (let key of Object.keys(bandwidthData).sort()) {
                let label = '';
                switch (key) {
                    case 'bs':
                        label = 'Transmitted';
                        break;
                    case 'br':
                        label = 'Received';
                        break;
                    default:
                        label = 'Unknown';
                }
                bandwidthDatasets.push({
                    label: label,
                });
            }
            return {
                title: 'Bandwidth',
                resource_label: 'Traffic',
                resource_type: 'bytes',
                resource_suffix: '',
                resource_fixed: 2,
                resource_min: 0,
                hide_zero: true,
                datasets: bandwidthDatasets,
            };
    }
    return undefined;
}
function getChartData(resource, data) {
    switch (resource) {
        case 'bandwidth':
            let bandwidthData = data;
            let bandwidthChart = [];
            for (let key of Object.keys(bandwidthData).sort()) {
                bandwidthChart.push(bandwidthData[key]);
            }
            return bandwidthChart;
    }
    return undefined;
}

