;// ./app/components/Profiles.js







const profilesStyle = `
.profiles-grid {
	display: grid;
	grid-template-columns: 1fr;
	gap: 0;
	margin: 8px 0 0 8px;
}
@media (min-width: 864px) {
	.profiles-grid {
		grid-template-columns: repeat(auto-fill, minmax(420px, 1fr));
	}
}
`;
class Profiles extends react.Component {
    constructor(props, context) {
        super(props, context);
        this.onResize = () => {
            this.setState({
                windowWidth: document.documentElement.clientWidth,
            });
        };
        this.onChange = () => {
            this.setState({
                profiles: stores_ProfilesStore.profiles,
                zeros: stores_ZerosStore.zeros,
            });
        };
        this.state = {
            profiles: stores_ProfilesStore.profiles,
            zeros: stores_ZerosStore.zeros,
            windowWidth: document.documentElement.clientWidth,
        };
    }
    componentDidMount() {
        stores_ProfilesStore.addChangeListener(this.onChange);
        stores_ZerosStore.addChangeListener(this.onChange);
        sync();
        ZeroActions_sync();
        window.addEventListener('resize', this.onResize);
        this.interval = setInterval(() => {
            sync(true);
            ZeroActions_sync(true);
        }, 1000);
    }
    componentWillUnmount() {
        stores_ProfilesStore.removeChangeListener(this.onChange);
        stores_ZerosStore.removeChangeListener(this.onChange);
        window.removeEventListener('resize', this.onResize);
        clearInterval(this.interval);
    }
    render() {
        let profilesDom = [];
        let profilesCount = this.state.profiles.length +
            this.state.zeros.length;
        let minimal = profilesCount > 3 && this.state.windowWidth < 864;
        let prflIds = new Set();
        let zeroIds = new Set();
        this.state.profiles.forEach((prfl) => {
            if (prflIds.has(prfl.id)) {
                return;
            }
            prflIds.add(prfl.id);
            profilesDom.push(react.createElement(Profile, { key: prfl.id, profile: prfl, minimal: minimal }));
        });
        this.state.zeros.forEach((zero) => {
            if (zeroIds.has(zero.id)) {
                return;
            }
            zeroIds.add(zero.id);
            profilesDom.push(react.createElement(Zero, { key: "zero-" + zero.id, zero: zero, minimal: minimal }));
        });
        return react.createElement("div", null,
            react.createElement("style", null, profilesStyle),
            react.createElement("div", { className: "profiles-grid" }, profilesDom));
    }
}

;// ./app/utils/LogUtils.js





async function readServiceLog() {
    let logData = "";
    try {
        let resp = await get('/log/service')
            .end();
        logData = resp.data;
    }
    catch (err) {
        err = new RequestError(err, "Logs: Service log request error");
        errorAlert2(err, 10);
    }
    return logData;
}
async function clearServiceLog() {
    try {
        await del('/log/service')
            .end();
    }
    catch (err) {
        err = new RequestError(err, "Logs: Service log request error");
        errorAlert2(err, 10);
    }
}
async function readClientLog() {
    let logData = "";
    let logPath = log();
    try {
        let exists = await fileExists(logPath);
        if (exists) {
            logData = await fileRead(logPath);
        }
    }
    catch (err) {
        errorAlert2(err, 10);
    }
    return logData;
}
async function clearClientLog() {
    try {
        await fileWrite(log(), "");
    }
    catch (err) {
        errorAlert2(err, 10);
    }
}

